(G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (V W : Set E3)
    (hV : IsOpen V) (hW : IsOpen W) (hVW : IsPreconnected (V ∩ W))
    (hpos : ∀ z ∈ W, ∀ v : E3, v ≠ 0 → 0 < ∑ a : Fin 3, ∑ b : Fin 3, v a * G z a b * v b)
