def sternKappa (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (L t : ℝ) : ℝ :=
  ∫ s in (0 : ℝ)..(2 * Real.pi), curvIntegrand G t L s


def sternVecEps (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (ε : ℝ) (x : E3) : Fin 3 → ℝ :=
  fun k => Real.sqrt (G x).det *
    ∑ l : Fin 3, (G x)⁻¹ k l * partialDeriv l (fun z => Real.sqrt ((G z)⁻¹ 0 0 + ε)) x


def sternPhiM (g : RiemannianMetric3 M) (u : M → ℝ) (ε : ℝ) (p : M) : ℝ :=
  Real.sqrt (g.gradInner u u p + ε)


def sternGaussM (g : RiemannianMetric3 M) (u : M → ℝ) (p : M) : ℝ :=
  levelGaussLoc (g.coeff (chartAt E3 p).symm) (fun y => u ((chartAt E3 p).symm y)) (chartAt E3 p p)


def sternAdmissible (Ω : Set M) {n : ℕ} (q : Fin n → M) (φ : Fin n → M → ℝ) : Prop :=
  ∃ (Ω' O : Set M), calPartition q φ Ω' ∧ IsOpen O ∧ Ω ⊆ O ∧ ∀ x ∈ O, ∑ j, φ j x = 1


def sternBulk (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (ε s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => Real.smoothTransition (β p / s) * g.lapM (sternPhiM g u ε) p)


def sternCollar (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (ε s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => s⁻¹ * deriv Real.smoothTransition (β p / s) *
    g.gradInner β (sternPhiM g u ε) p)


def sternBandJ (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => Real.smoothTransition (β p / s) *
      Real.sqrt (g.gradInner u u p) * sternGaussM g u p) -
    calVolSum g q φ S (fun p => s⁻¹ * deriv Real.smoothTransition (β p / s) *
      g.gradInner β (fun x => Real.sqrt (g.gradInner u u x)) p)

