def hessLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (i j : Fin 3) (y : E3) : ℝ :=
  partialDeriv i (partialDeriv j f) y - ∑ k : Fin 3, christoffel G k i j y * partialDeriv k f y


def lapLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, (G y)⁻¹ i j * hessLoc G f i j y


def staticLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (i j : Fin 3) (y : E3) : ℝ :=
  f y * ricci G i j y - hessLoc G f i j y + lapLoc G f y * G y i j


def staticSymLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (i j : Fin 3) (y : E3) : ℝ :=
  (staticLoc G f i j y + staticLoc G f j i y) / 2


def RiemannianMetric3.lapM (g : RiemannianMetric3 M) (u : M → ℝ) (p : M) : ℝ :=
  lapLoc (g.coeff (chartAt E3 p).symm) (fun y => u ((chartAt E3 p).symm y)) (chartAt E3 p p)

def lapLocal (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (u : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, (G y)⁻¹ i j *
    (partialDeriv i (fun z => partialDeriv j u z) y -
      ∑ k : Fin 3, christoffel G k i j y * partialDeriv k u y)


def lapM (g : RiemannianMetric3 M) (f : M → ℝ) (p : M) : ℝ :=
  lapLocal (g.coeff (chartAt E3 p).symm) (f ∘ (chartAt E3 p).symm) (chartAt E3 p p)


def farPot (δ : ℝ) (x : E3) : ℝ := ‖x‖⁻¹ + ‖x‖ ^ (-1 - δ)


def smax1 (u : ℝ) : ℝ := ∫ t in (-1 : ℝ)..u, Real.smoothTransition ((t + 1) / 2)

def jacMat (Y : E3 → E3) (x : E3) : Matrix (Fin 3) (Fin 3) ℝ :=
  Matrix.of fun i a => (fderiv ℝ Y x (e a)) i


def piolaVec (Y : E3 → E3) (U : E3 → Fin 3 → ℝ) (x : E3) : Fin 3 → ℝ :=
  fun a => ∑ i : Fin 3, (jacMat Y x).adjugate a i * U (Y x) i


def jacCurlVec (Y : E3 → E3) (x : E3) : Fin 3 → ℝ :=
  fun b => ∑ a : Fin 3,
    partialDeriv a (fun z => (fderiv ℝ Y z (e a)) b - (fderiv ℝ Y z (e b)) a) x


def cutoffPiolaField (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Y : E3 → E3) (R₁ c : ℝ) (x : E3) :
    Fin 3 → ℝ :=
  fun a => if R₁ < ‖x‖ then
    ∑ i : Fin 3, (jacMat Y x).adjugate a i *
      (Real.smoothTransition (‖Y x‖ - c) * admVec G (Y x) i) else 0

def sternPsi (Φ : EndChart M) (Y : E3 → E3) (x : E3) : M := Φ.Φ (Y x)


def sternOuter (Φ : EndChart M) (Y : E3 → E3) (L : ℝ) : Set M :=
  sternPsi Φ Y '' {x : E3 | ¬ (|x 0| ≤ L ∧ (x 1) ^ 2 + (x 2) ^ 2 ≤ L ^ 2)}


def sternOuterClosed (Φ : EndChart M) (Y : E3 → E3) (L : ℝ) : Set M :=
  sternPsi Φ Y '' {x : E3 | ¬ (|x 0| < L ∧ (x 1) ^ 2 + (x 2) ^ 2 < L ^ 2)}


def sternDomain (Φ : EndChart M) (β : M → ℝ) (Y : E3 → E3) (L : ℝ) : Set M :=
  {p : M | 0 ≤ β p} \ sternOuter Φ Y L


def sternSide (Φ : EndChart M) (Y : E3 → E3) (L : ℝ) : Set M :=
  sternPsi Φ Y '' {x : E3 | |x 0| < L ∧ (x 1) ^ 2 + (x 2) ^ 2 = L ^ 2}

def sepPlaneProj (a : Fin 3) (y : E3) : E3 := y - (y a) • e a


def sepCyl (a : Fin 3) (c : E3) (r δ : ℝ) : Set E3 :=
  {z : E3 | ‖sepPlaneProj a (z - c)‖ < r ∧ |z a - c a| < δ}


def sepDensDiv (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (X : E3 → E3) (y : E3) : ℝ :=
  ∑ i : Fin 3, partialDeriv i (fun z => Real.sqrt (G z).det * X z i) y


def sepPerG (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F U : Set E3) : ENNReal :=
  ⨆ (X : E3 → E3) (_ : ContDiff ℝ ∞ X ∧ HasCompactSupport X ∧ tsupport X ⊆ U ∧
      ∀ y, ∑ i : Fin 3, ∑ j : Fin 3, G y i j * X y i * X y j ≤ 1),
    ENNReal.ofReal (∫ y in F, sepDensDiv G X y)


def sepIsPerMin (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F U : Set E3) : Prop :=
  MeasurableSet F ∧
  (∀ V : Set E3, IsOpen V → IsCompact (closure V) → closure V ⊆ U → sepPerG G F V < ⊤) ∧
  ∀ F' V K : Set E3, MeasurableSet F' → IsOpen V → IsCompact (closure V) → closure V ⊆ U →
    IsCompact K → K ⊆ V → symmDiff F F' ⊆ K → sepPerG G F V ≤ sepPerG G F' V


def sepChartNull (S : Set M) : Prop :=
  ∀ p : M, volume (chartAt E3 p '' (S ∩ (chartAt E3 p).source)) = 0


def sepChartMeas (S : Set M) : Prop :=
  ∀ p : M, MeasurableSet (chartAt E3 p '' (S ∩ (chartAt E3 p).source))


def sepRiemPer (g : RiemannianMetric3 M) (F U : Set M) : ENNReal :=
  ⨆ (n : ℕ) (p : Fin n → M) (W : Fin n → Set M)
    (_ : (∀ k, IsOpen (W k) ∧ W k ⊆ U ∩ (chartAt E3 (p k)).source) ∧
      Pairwise (fun k l => Disjoint (W k) (W l))),
    ∑ k, sepPerG (g.coeff (chartAt E3 (p k)).symm)
      (chartAt E3 (p k) '' (F ∩ (chartAt E3 (p k)).source)) (chartAt E3 (p k) '' W k)

def mcS (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (z : E3) (ξ : Fin 3 → ℝ) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, (G z)⁻¹ i j * ξ i * ξ j


def mcP (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (z : E3) (ξ : Fin 3 → ℝ) (i j : Fin 3) : ℝ :=
  (G z)⁻¹ i j / Real.sqrt (mcS G z ξ) -
    (∑ a : Fin 3, (G z)⁻¹ i a * ξ a) * (∑ b : Fin 3, (G z)⁻¹ j b * ξ b) /
      Real.sqrt (mcS G z ξ) ^ 3


def mcR (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (z : E3) (ξ : Fin 3 → ℝ) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, mcP G z ξ i j * ∑ k : Fin 3, christoffel G k i j z * ξ k

def smthLift (a : Fin 3) (x : Fin 2 → ℝ) (t : ℝ) : E3 :=
  (EuclideanSpace.equiv (Fin 3) ℝ).symm (Fin.insertNth a t x)


def smthHoriz (a : Fin 3) (z : E3) : Fin 2 → ℝ := fun k => z (a.succAbove k)


def smthGrad (v : (Fin 2 → ℝ) → ℝ) (x : Fin 2 → ℝ) : Fin 2 → ℝ :=
  fun k => fderiv ℝ v x (Pi.single k 1)


def smthDisc (a : Fin 3) (c : E3) (ρ : ℝ) : Set (Fin 2 → ℝ) :=
  {x | ∑ k : Fin 2, (x k - c (a.succAbove k)) ^ 2 < ρ ^ 2}


def smthCovec (a : Fin 3) (p : Fin 2 → ℝ) : Fin 3 → ℝ :=
  (Fin.insertNth a (1 : ℝ) (-p) : Fin 3 → ℝ)


def smthLag (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (a : Fin 3)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  Real.sqrt (G (smthLift a w.1 w.2.1)).det *
    Real.sqrt (∑ i : Fin 3, ∑ j : Fin 3, (G (smthLift a w.1 w.2.1))⁻¹ i j *
      smthCovec a w.2.2 i * smthCovec a w.2.2 j)


def smthELop (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ) (v : (Fin 2 → ℝ) → ℝ)
    (x : Fin 2 → ℝ) : ℝ :=
  fderiv ℝ Λ (x, v x, smthGrad v x) (0, 1, 0) -
    ∑ k : Fin 2, fderiv ℝ (fun y => fderiv ℝ Λ (y, v y, smthGrad v y) (0, 0, Pi.single k 1)) x
      (Pi.single k 1)

def calTheta (r₁ η t : ℝ) : ℝ := Real.smoothTransition (2 * ((t - r₁) / η) - 1)


def calSigma (ρ : M → ℝ) (r₁ : ℝ) (A : Set M) (x : M) : ℝ :=
  ({p : M | r₁ < ρ p} \ A).indicator (fun _ => (1 : ℝ)) x - A.indicator (fun _ => (1 : ℝ)) x


def calUnitNormal (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) (i : Fin 3) : ℝ :=
  (Real.sqrt (∑ a : Fin 3, ∑ b : Fin 3, (G y)⁻¹ a b * partialDeriv a f y * partialDeriv b f y))⁻¹ *
    ∑ k : Fin 3, (G y)⁻¹ i k * partialDeriv k f y

def hspSector (B : Set E3) {k : ℕ} (φ : Fin k → E3 → ℝ) (s : Fin k → Bool) : Set E3 :=
  {z | z ∈ B ∧ ∀ i, 0 < (if s i then (1 : ℝ) else -1) * φ i z}


def hspSectorPer (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (B : Set E3) {k : ℕ}
    (φ : Fin k → E3 → ℝ) (E W : Set E3) : ENNReal :=
  ∑ s : Fin k → Bool, sepPerG G (E ∩ hspSector B φ s) W

def lmcJAgree (a : Fin 3) (y₀ : E3) (F₁ F₂ : E3 → ℝ) (d : ℝ) : Prop :=
  DifferentiableAt ℝ F₁ y₀ ∧ DifferentiableAt ℝ F₂ y₀ ∧ F₁ y₀ = F₂ y₀ ∧
    partialDeriv a F₁ y₀ - partialDeriv a F₂ y₀ = d

def sfrTheta (φ : E3 → ℝ) (τ : ℝ) (z : E3) : ℝ :=
  Real.smoothTransition (2 * (φ z / τ) - 1)


def sfrWall (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (φ χ : E3 → ℝ) (τ : ℝ) (Y : E3 → E3) :
    E3 → E3 :=
  fun z => sfrTheta φ τ z • Y z - ((1 - sfrTheta φ τ z) * χ z) • hcrNormalField G φ z

def ejpS (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, (G y)⁻¹ i j * partialDeriv i Φ y * partialDeriv j Φ y


def ejpPsi (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) : ℝ :=
  (Real.sqrt (ejpS G Φ y))⁻¹


def ejpN (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) (a : Fin 3) : ℝ :=
  ∑ b : Fin 3, (G y)⁻¹ a b * partialDeriv b Φ y


def ejpP (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) (a b : Fin 3) : ℝ :=
  (G y)⁻¹ a b - ejpN G Φ y a * ejpN G Φ y b / ejpS G Φ y


def ejpRic (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) : ℝ :=
  (∑ j : Fin 3, ∑ k : Fin 3, ricci G j k y * ejpN G Φ y j * ejpN G Φ y k) / ejpS G Φ y


def ejpJac (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3,
    (G y)⁻¹ i j * partialDeriv i (levelMeanCurvCoord G Φ) y * partialDeriv j Φ y


def ejpPot (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y : E3) : ℝ :=
  secondFundSq G Φ y + ejpRic G Φ y

def epaPlaneEmb (a : Fin 3) (x : E2) : E3 := ∑ k : Fin 2, x k • e (a.succAbove k)


def epaPlaneCoord (a : Fin 3) (z : E3) : E2 := ∑ k : Fin 2, z (a.succAbove k) • e2 k


def epaGraphParam (a : Fin 3) (u : E3 → ℝ) (x : E2) : E3 :=
  epaPlaneEmb a x + u (epaPlaneEmb a x) • e a

def gsTan (F : E2 → E3) (i : Fin 2) (x : E2) : E3 := fderiv ℝ F x (e2 i)


def gsHessF (F : E2 → E3) (i j : Fin 2) (x : E2) : E3 :=
  fderiv ℝ (fun y => fderiv ℝ F y (e2 j)) x (e2 i)


def gsCrossN (F : E2 → E3) (x : E2) : Fin 3 → ℝ :=
  ![gsTan F 0 x 1 * gsTan F 1 x 2 - gsTan F 0 x 2 * gsTan F 1 x 1,
    gsTan F 0 x 2 * gsTan F 1 x 0 - gsTan F 0 x 0 * gsTan F 1 x 2,
    gsTan F 0 x 0 * gsTan F 1 x 1 - gsTan F 0 x 1 * gsTan F 1 x 0]


def gsNormLen (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (x : E2) : ℝ :=
  Real.sqrt (∑ k : Fin 3, ∑ l : Fin 3, (G (F x))⁻¹ k l * gsCrossN F x k * gsCrossN F x l)


def gsCovHess (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (i j : Fin 2) (x : E2)
    (k : Fin 3) : ℝ :=
  gsHessF F i j x k + ∑ m : Fin 3, ∑ n : Fin 3,
    christoffel G k m n (F x) * gsTan F i x m * gsTan F j x n


def gsSff (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (i j : Fin 2) (x : E2) : ℝ :=
  (∑ k : Fin 3, gsCrossN F x k * gsCovHess G F i j x k) / gsNormLen G F x


def gsInner (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (S T : Fin 2 → Fin 2 → E2 → ℝ) (x : E2) : ℝ :=
  ∑ i : Fin 2, ∑ j : Fin 2, ∑ a : Fin 2, ∑ b : Fin 2,
    (h x)⁻¹ i a * (h x)⁻¹ j b * S i j x * T a b x


def gsTrace (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (S : Fin 2 → Fin 2 → E2 → ℝ) (x : E2) : ℝ :=
  ∑ i : Fin 2, ∑ j : Fin 2, (h x)⁻¹ i j * S i j x


def gsSffSq (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (x : E2) : ℝ :=
  gsInner (pullMetric2 G F) (gsSff G F) (gsSff G F) x


def gsMeanCurv (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (x : E2) : ℝ :=
  gsTrace (pullMetric2 G F) (gsSff G F) x


def gsAmbPlane (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (x : E2) : ℝ :=
  ∑ l : Fin 3, ∑ i : Fin 3, ∑ j : Fin 3, ∑ k : Fin 3, ∑ m : Fin 3,
    G (F x) m l * riemannLocal G l i j k (F x) *
      gsTan F 0 x i * gsTan F 1 x j * gsTan F 1 x k * gsTan F 0 x m


def gsAmbCod (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (k i j : Fin 2) (x : E2) : ℝ :=
  (∑ l : Fin 3, ∑ a : Fin 3, ∑ b : Fin 3, ∑ c : Fin 3,
    gsCrossN F x l * riemannLocal G l a b c (F x) *
      gsTan F k x a * gsTan F i x b * gsTan F j x c) / gsNormLen G F x


def gsCovD1 (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (w : Fin 2 → E2 → ℝ) (i j : Fin 2)
    (x : E2) : ℝ :=
  pd2 i (w j) x - ∑ m : Fin 2, christoffel2 h m i j x * w m x


def gsCovD2 (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (S : Fin 2 → Fin 2 → E2 → ℝ) (k i j : Fin 2)
    (x : E2) : ℝ :=
  pd2 k (S i j) x - ∑ m : Fin 2, christoffel2 h m k i x * S m j x
    - ∑ m : Fin 2, christoffel2 h m k j x * S i m x


def gsCovD3 (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (C : Fin 2 → Fin 2 → Fin 2 → E2 → ℝ)
    (l k i j : Fin 2) (x : E2) : ℝ :=
  pd2 l (C k i j) x - ∑ m : Fin 2, christoffel2 h m l k x * C m i j x
    - ∑ m : Fin 2, christoffel2 h m l i x * C k m j x
    - ∑ m : Fin 2, christoffel2 h m l j x * C k i m x


def gsCodazzi (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (S : Fin 2 → Fin 2 → E2 → ℝ) (k i j : Fin 2)
    (x : E2) : ℝ :=
  gsCovD2 h S k i j x - gsCovD2 h S i k j x


def gsSimonsE (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (C : Fin 2 → Fin 2 → Fin 2 → E2 → ℝ)
    (i j : Fin 2) (x : E2) : ℝ :=
  gsCovD1 h (fun j' y => ∑ k : Fin 2, ∑ l : Fin 2, (h y)⁻¹ k l * C k j' l y) i j x
    + ∑ k : Fin 2, ∑ l : Fin 2, (h x)⁻¹ k l * gsCovD3 h C l k i j x

def sprayGam (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (y v : E3) : E3 :=
  (EuclideanSpace.equiv (Fin 3) ℝ).symm
    (fun k => ∑ a : Fin 3, ∑ b : Fin 3, christoffel G k a b y * v a * v b)



def sprayA (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (Φ : E3 → ℝ) (y v : E3) : E3 :=
  ((∑ i : Fin 3, ∑ j : Fin 3, hessLoc G Φ i j y * v i * v j) /
      (∑ a : Fin 3, ∑ b : Fin 3, (G y)⁻¹ a b * partialDeriv a Φ y * partialDeriv b Φ y)) •
    (EuclideanSpace.equiv (Fin 3) ℝ).symm
      (fun k => ∑ l : Fin 3, (G y)⁻¹ k l * partialDeriv l Φ y)


def sprayQ (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) {N : ℕ} (Φ ψ : Fin N → E3 → ℝ) (y v : E3) : E3 :=
  -sprayGam G y v - ∑ i : Fin N, ψ i y • sprayA G (Φ i) y v

def ggeGam1 (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (m i j : Fin 2) (x : E2) : ℝ :=
  (1 / 2 : ℝ) * (pd2 i (fun z => h z j m) x + pd2 j (fun z => h z i m) x - pd2 m (fun z => h z i j) x)


def ggeRiem0110 (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (x : E2) : ℝ :=
  pd2 0 (ggeGam1 h 0 1 1) x - pd2 1 (ggeGam1 h 0 0 1) x
    - ∑ l : Fin 2, ggeGam1 h l 0 0 x * christoffel2 h l 1 1 x
    + ∑ l : Fin 2, ggeGam1 h l 1 0 x * christoffel2 h l 0 1 x

def gcNu (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (x : E2) (l : Fin 3) : ℝ :=
  (∑ k : Fin 3, (G (F x))⁻¹ l k * gsCrossN F x k) / gsNormLen G F x



def gcCovAlong (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (F : E2 → E3) (V : E2 → Fin 3 → ℝ)
    (k : Fin 2) (x : E2) (l : Fin 3) : ℝ :=
  pd2 k (fun y => V y l) x + ∑ a : Fin 3, ∑ b : Fin 3,
    christoffel G l a b (F x) * gsTan F k x a * V x b

def mseQC : ℕ → NNReal → ((Fin 2 → ℝ) → ℝ) → Set (Fin 2 → ℝ) → Prop
  | 0, B, f, S => (∀ x ∈ S, |f x| ≤ (B : ℝ)) ∧ HolderOnWith B (1 / 2 : NNReal) f S
  | s + 1, B, f, S => ((∀ x ∈ S, |f x| ≤ (B : ℝ)) ∧ HolderOnWith B (1 / 2 : NNReal) f S) ∧
      ∀ m : Fin 2, mseQC s B (fun x => smthGrad f x m) S

def mseDivSol (a : (Fin 2 → ℝ) → Fin 2 → Fin 2 → ℝ) (F : (Fin 2 → ℝ) → Fin 2 → ℝ)
    (w : (Fin 2 → ℝ) → ℝ) (S : Set (Fin 2 → ℝ)) : Prop :=
  ∀ x ∈ S, ∑ i : Fin 2, smthGrad (fun y => ∑ j : Fin 2, a y i j * smthGrad w y j - F y i) x i = 0

def mseLp (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ) (i : Fin 2)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  fderiv ℝ Λ w (0, 0, Pi.single i 1)

def mseLz (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  fderiv ℝ Λ w (0, 1, 0)

def mseLpp (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ) (i j : Fin 2)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  fderiv ℝ (mseLp Λ i) w (0, 0, Pi.single j 1)

def mseLpx (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ) (i m : Fin 2)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  fderiv ℝ (mseLp Λ i) w (Pi.single m 1, 0, 0)

def mseLpz (Λ : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ) → ℝ) (i : Fin 2)
    (w : (Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) : ℝ :=
  fderiv ℝ (mseLp Λ i) w (0, 1, 0)

def mseParamSet (a : Fin 3) (c : E3) (ρ : ℝ) : Set ((Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) :=
  {w | ∑ k : Fin 2, (w.1 k - c (a.succAbove k)) ^ 2 ≤ (3 * ρ) ^ 2 ∧ |w.2.1 - c a| ≤ 9 * ρ ∧
    ‖w.2.2‖ ≤ 2}

def mseLagDom (a : Fin 3) (Ω : Set E3) : Set ((Fin 2 → ℝ) × ℝ × (Fin 2 → ℝ)) :=
  {w | smthLift a w.1 w.2.1 ∈ Ω}

def gbW (H : ℝ → E2 → Matrix (Fin 2) (Fin 2) ℝ) (t : ℝ) (x : E2) (e : Fin 2) : ℝ :=
  ∑ b : Fin 2, ∑ c : Fin 2, (H t x)⁻¹ b c * deriv (fun s => christoffel2 (H s) e b c x) t -
    ∑ b : Fin 2, (H t x)⁻¹ e b * ∑ c : Fin 2, deriv (fun s => christoffel2 (H s) c c b x) t

def pcrHolLoc (α : ℝ) (m : ℕ) (w : E2 → ℝ) (U : Set E2) : Prop :=
  ContDiffOn ℝ m w U ∧ ∀ x ∈ U, ∃ ρ : ℝ, 0 < ρ ∧ Metric.ball x ρ ⊆ U ∧ ∃ C : ℝ,
    ∀ y ∈ Metric.ball x ρ, ∀ z ∈ Metric.ball x ρ,
      ‖iteratedFDeriv ℝ m w y - iteratedFDeriv ℝ m w z‖ ≤ C * dist y z ^ α


def pcrClass {X : Type*} [TopologicalSpace X] {S : Set X} (P : EigPatchedSurface X S)
    (α : ℝ) (m : ℕ) (u : X → ℝ) : Prop :=
  (∀ q, q ∉ S → u q = 0) ∧ ∀ j, pcrHolLoc α m (fun x => u (P.param j x)) (P.W j)


def pcrH (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (w : E2 → ℝ) (x : E2) : ℝ :=
  levelMeanCurvCoord G (fun y => y 0 - w (hpProj y)) (hpLift (w x) x)

def iterPartial {j : ℕ} (σ : Fin j → Fin 3) (v : E3 → ℝ) : E3 → ℝ :=
  List.foldr (fun k w => partialDeriv k w) v (List.ofFn σ)


def ellOp (a : E3 → Matrix (Fin 3) (Fin 3) ℝ) (b : E3 → Fin 3 → ℝ) (w : E3 → ℝ) : E3 → ℝ :=
  fun y => ∑ i : Fin 3, ∑ j : Fin 3, a y i j * partialDeriv i (partialDeriv j w) y
    + ∑ l : Fin 3, b y l * partialDeriv l w y


def sqSum (n : ℕ) (v : E3 → ℝ) : E3 → ℝ :=
  fun y => ∑ σ : Fin n → Fin 3, (iterPartial σ v y) ^ 2

def gradInnerLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f h : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, (G y)⁻¹ i j * partialDeriv i f y * partialDeriv j h y

def gradSqLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  gradInnerLoc G f f y

def gradUpLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) (i : Fin 3) : ℝ :=
  ∑ a : Fin 3, (G y)⁻¹ i a * partialDeriv a f y

def hessSqLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, ∑ a : Fin 3, ∑ b : Fin 3,
    (G y)⁻¹ i a * (G y)⁻¹ j b * hessLoc G f i j y * hessLoc G f a b y

def hessGGLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (h f : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, gradUpLoc G f y i * gradUpLoc G f y j * hessLoc G h i j y

def hessGradSqLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, ∑ a : Fin 3, ∑ b : Fin 3,
    (G y)⁻¹ i j * (hessLoc G f i a y * gradUpLoc G f y a) * (hessLoc G f j b y * gradUpLoc G f y b)

def ricGradLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  ∑ i : Fin 3, ∑ j : Fin 3, gradUpLoc G f y i * gradUpLoc G f y j * ricci G i j y

def levelGaussLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (y : E3) : ℝ :=
  let N2 := gradSqLoc G f y
  let hgg := hessGGLoc G f f y
  (1 / 2 : ℝ) * (scalarCurvatureLocal G y - 2 * ricGradLoc G f y / N2
    + (lapLoc G f y - hgg / N2) ^ 2 / N2
    - (hessSqLoc G f y - 2 * hessGradSqLoc G f y / N2 + hgg ^ 2 / N2 ^ 2) / N2)

def sternPhiLoc (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (f : E3 → ℝ) (ε : ℝ) (y : E3) : ℝ :=
  Real.sqrt (gradSqLoc G f y + ε)

def sternKappa (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (L t : ℝ) : ℝ :=
  ∫ s in (0 : ℝ)..(2 * Real.pi), curvIntegrand G t L s


def sternVecEps (G : E3 → Matrix (Fin 3) (Fin 3) ℝ) (ε : ℝ) (x : E3) : Fin 3 → ℝ :=
  fun k => Real.sqrt (G x).det *
    ∑ l : Fin 3, (G x)⁻¹ k l * partialDeriv l (fun z => Real.sqrt ((G z)⁻¹ 0 0 + ε)) x


def sternPhiM (g : RiemannianMetric3 M) (u : M → ℝ) (ε : ℝ) (p : M) : ℝ :=
  Real.sqrt (g.gradInner u u p + ε)


def sternGaussM (g : RiemannianMetric3 M) (u : M → ℝ) (p : M) : ℝ :=
  levelGaussLoc (g.coeff (chartAt E3 p).symm) (fun y => u ((chartAt E3 p).symm y)) (chartAt E3 p p)


def sternAdmissible (Ω : Set M) {n : ℕ} (q : Fin n → M) (φ : Fin n → M → ℝ) : Prop :=
  ∃ (Ω' O : Set M), calPartition q φ Ω' ∧ IsOpen O ∧ Ω ⊆ O ∧ ∀ x ∈ O, ∑ j, φ j x = 1


def sternBulk (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (ε s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => Real.smoothTransition (β p / s) * g.lapM (sternPhiM g u ε) p)


def sternCollar (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (ε s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => s⁻¹ * deriv Real.smoothTransition (β p / s) *
    g.gradInner β (sternPhiM g u ε) p)


def sternBandJ (g : RiemannianMetric3 M) (β u : M → ℝ) {n : ℕ} (q : Fin n → M)
    (φ : Fin n → M → ℝ) (S : Set M) (s : ℝ) : ℝ :=
  calVolSum g q φ S (fun p => Real.smoothTransition (β p / s) *
      Real.sqrt (g.gradInner u u p) * sternGaussM g u p) -
    calVolSum g q φ S (fun p => s⁻¹ * deriv Real.smoothTransition (β p / s) *
      g.gradInner β (fun x => Real.sqrt (g.gradInner u u x)) p)

def sternTheta (R₁ : ℝ) (x : E3) : ℝ := Real.smoothTransition (‖x‖ - (R₁ + 1))

def sternKset (R₁ L : ℝ) : Set E3 :=
  {x : E3 | |x 0| ≤ L ∧ x 1 ^ 2 + x 2 ^ 2 ≤ L ^ 2 ∧ R₁ + 1 ≤ ‖x‖}

def sternWt (g : RiemannianMetric3 M) (β u : M → ℝ)
    (P : PartialDiffeomorph 𝓘(ℝ, E3) 𝓘(ℝ, E3) E3 M ∞) (R₁ s ε : ℝ) (x : E3) : E3 :=
  sternTheta R₁ x • (EuclideanSpace.equiv (Fin 3) ℝ).symm (fun i =>
    Real.smoothTransition (β (P x) / s) * ∑ k : Fin 3, (g.coeff P x)⁻¹ i k *
      partialDeriv k (fun z => sternPhiM g u ε (P z)) x)

def pcgbTransport {X : Type*} [TopologicalSpace X] {S : Set X} (P : EigPatchedSurface X S)
    (j₀ : Fin P.n) (G : E2 → ℝ) : X → ℝ :=
  (P.O j₀ ∩ S).indicator (fun q => G (P.proj j₀ q))

def fplDt (f : ℝ × ℝ → ℝ) (p : ℝ × ℝ) : ℝ := fderiv ℝ f p (1, 0)


def fplDs (f : ℝ × ℝ → ℝ) (p : ℝ × ℝ) : ℝ := fderiv ℝ f p (0, 1)


def fplV0 (a b w : ℝ × ℝ → ℝ) (p : ℝ × ℝ) : ℝ := a p * fplDt w p + b p * fplDs w p


def fplV1 (b c w : ℝ × ℝ → ℝ) (p : ℝ × ℝ) : ℝ := b p * fplDt w p + c p * fplDs w p


def fplCylData (T C₁ : ℝ) (a b c w : ℝ × ℝ → ℝ) : Prop :=
  ContDiffOn ℝ ∞ a {p : ℝ × ℝ | p.1 < T} ∧ ContDiffOn ℝ ∞ b {p : ℝ × ℝ | p.1 < T} ∧
  ContDiffOn ℝ ∞ c {p : ℝ × ℝ | p.1 < T} ∧ ContDiffOn ℝ ∞ w {p : ℝ × ℝ | p.1 < T} ∧
  (∀ p : ℝ × ℝ, p.1 < T →
    a (p.1, p.2 + 2 * Real.pi) = a p ∧ b (p.1, p.2 + 2 * Real.pi) = b p ∧
    c (p.1, p.2 + 2 * Real.pi) = c p ∧ w (p.1, p.2 + 2 * Real.pi) = w p) ∧
  (∀ p : ℝ × ℝ, p.1 < T →
    a p * c p - b p ^ 2 = 1 ∧ 1 / 2 ≤ a p ∧ a p ≤ 2 ∧ |b p| ≤ 2 ∧
    |fplDt a p| ≤ C₁ * Real.exp p.1 ∧ |fplDs a p| ≤ C₁ * Real.exp p.1 ∧
    |fplDt b p| ≤ C₁ * Real.exp p.1 ∧ |fplDs b p| ≤ C₁ * Real.exp p.1 ∧
    fplDt (fplV0 a b w) p + fplDs (fplV1 b c w) p = 0)


def fplH (a w : ℝ × ℝ → ℝ) (t : ℝ) : ℝ :=
  ∫ θ in (-Real.pi)..Real.pi, a (t, θ) * w (t, θ) ^ 2


def fplD (a b w : ℝ × ℝ → ℝ) (t : ℝ) : ℝ :=
  ∫ θ in (-Real.pi)..Real.pi, w (t, θ) * fplV0 a b w (t, θ)


def fplX (a b w : ℝ × ℝ → ℝ) (t : ℝ) : ℝ :=
  ∫ θ in (-Real.pi)..Real.pi, fplV0 a b w (t, θ) ^ 2 / a (t, θ)


def fplY (a w : ℝ × ℝ → ℝ) (t : ℝ) : ℝ :=
  ∫ θ in (-Real.pi)..Real.pi, fplDs w (t, θ) ^ 2 / a (t, θ)

def cylPhi (x₀ : E2) (P : Matrix (Fin 2) (Fin 2) ℝ) (p : ℝ × ℝ) : E2 :=
  x₀ + Real.exp p.1 • (EuclideanSpace.equiv (Fin 2) ℝ).symm
    (fun i => P i 0 * Real.cos p.2 + P i 1 * Real.sin p.2)

def cylA (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (x : E2) (i j : Fin 2) : ℝ :=
  Real.sqrt (h x).det * (h x)⁻¹ i j

def cylM00 (P : Matrix (Fin 2) (Fin 2) ℝ) (A00 A01 A11 : ℝ) : ℝ :=
  P 1 1 ^ 2 * A00 - 2 * P 1 1 * P 0 1 * A01 + P 0 1 ^ 2 * A11

def cylM01 (P : Matrix (Fin 2) (Fin 2) ℝ) (A00 A01 A11 : ℝ) : ℝ :=
  -(P 1 1 * P 1 0 * A00) + (P 1 1 * P 0 0 + P 0 1 * P 1 0) * A01 - P 0 1 * P 0 0 * A11

def cylM11 (P : Matrix (Fin 2) (Fin 2) ℝ) (A00 A01 A11 : ℝ) : ℝ :=
  P 1 0 ^ 2 * A00 - 2 * P 1 0 * P 0 0 * A01 + P 0 0 ^ 2 * A11

def cylRotA (θ m00 m01 m11 : ℝ) : ℝ :=
  Real.cos θ ^ 2 * m00 + 2 * Real.cos θ * Real.sin θ * m01 + Real.sin θ ^ 2 * m11

def cylRotB (θ m00 m01 m11 : ℝ) : ℝ :=
  -(Real.cos θ * Real.sin θ * m00) + (Real.cos θ ^ 2 - Real.sin θ ^ 2) * m01 +
    Real.cos θ * Real.sin θ * m11

def cylRotC (θ m00 m01 m11 : ℝ) : ℝ :=
  Real.sin θ ^ 2 * m00 - 2 * Real.cos θ * Real.sin θ * m01 + Real.cos θ ^ 2 * m11

def pcgbBdrPull (h : E2 → Matrix (Fin 2) (Fin 2) ℝ) (Ψ : E2 → E2) (z : E2) :
    Matrix (Fin 2) (Fin 2) ℝ :=
  Matrix.of fun c d => ∑ c' : Fin 2, ∑ d' : Fin 2,
    fderiv ℝ Ψ z (e2 c) c' * h (Ψ z) c' d' * fderiv ℝ Ψ z (e2 d) d'

def pcgbBdrVec (G : Fin 2 → E2 → ℝ) (Ψ : E2 → E2) (k : Fin 2) (z : E2) : ℝ :=
  ∑ c : Fin 2, fderiv ℝ Ψ z (e2 k) c * G c (Ψ z)

def pcgbF2P : E3 →L[ℝ] E2 :=
  (EuclideanSpace.proj (0 : Fin 3) : E3 →L[ℝ] ℝ).smulRight (e2 0) +
    (EuclideanSpace.proj (1 : Fin 3) : E3 →L[ℝ] ℝ).smulRight (e2 1)


def pcgbF2A (A : E2 → Matrix (Fin 2) (Fin 2) ℝ) (x : E3) : Matrix (Fin 3) (Fin 3) ℝ :=
  !![A (pcgbF2P x) 0 0, A (pcgbF2P x) 0 1, 0;
     A (pcgbF2P x) 1 0, A (pcgbF2P x) 1 1, 0;
     0, 0, 1]


def pcgbF2G (G : Fin 2 → E2 → ℝ) : Fin 3 → E3 → ℝ :=
  ![fun x => G 0 (pcgbF2P x), fun x => G 1 (pcgbF2P x), fun _ => 0]

def pcgbJv1 (H : Matrix (Fin 2) (Fin 2) ℝ) (x₀ x : E2) (p : Fin 2) : ℝ :=
  ∑ b : Fin 2, (H p b + H b p) * (x - x₀) b

def pcgbJv2 (T : Fin 2 → Fin 2 → Fin 2 → ℝ) (x₀ x : E2) (p : Fin 2) : ℝ :=
  ∑ b : Fin 2, ∑ c : Fin 2, (T p b c + T b p c + T b c p) * (x - x₀) b * (x - x₀) c

def pcgbJv3 (U : Fin 2 → Fin 2 → Fin 2 → Fin 2 → ℝ) (x₀ x : E2) (p : Fin 2) : ℝ :=
  ∑ b : Fin 2, ∑ c : Fin 2, ∑ d : Fin 2,
    (U p b c d + U b p c d + U b c p d + U b c d p) * (x - x₀) b * (x - x₀) c * (x - x₀) d

def pcgbJA1 (g1 : Fin 2 → Matrix (Fin 2) (Fin 2) ℝ) (x₀ x : E2) (p q : Fin 2) : ℝ :=
  ∑ k : Fin 2, g1 k p q * (x - x₀) k

def pcgbJA2 (g2 : Fin 2 → Fin 2 → Matrix (Fin 2) (Fin 2) ℝ) (x₀ x : E2) (p q : Fin 2) : ℝ :=
  (1 / 2 : ℝ) * ∑ k : Fin 2, ∑ l : Fin 2, g2 k l p q * (x - x₀) k * (x - x₀) l

def pcgbJE5 (Hi : Matrix (Fin 2) (Fin 2) ℝ) (A1 A2 : Fin 2 → Fin 2 → ℝ) (v1 v2 v3 : Fin 2 → ℝ) : ℝ :=
  ∑ p : Fin 2, ∑ q : Fin 2,
    (Hi p q * (v2 p * v3 q + v3 p * v2 q + v3 p * v3 q)
      + A1 p q * (v1 p * v3 q + v3 p * v1 q + v2 p * v2 q + v2 p * v3 q + v3 p * v2 q + v3 p * v3 q)
      + A2 p q * (v1 p * v2 q + v2 p * v1 q + v1 p * v3 q + v3 p * v1 q + v2 p * v2 q
          + v2 p * v3 q + v3 p * v2 q + v3 p * v3 q))
